mapper.select:
WITH ranked_users AS ( SELECT u.*, (SELECT COUNT(1) FROM user t WHERE t.id != 1 AND (t.rating > u.rating OR (t.rating = u.rating AND UNIX_TIMESTAMP(t.create_time) < UNIX_TIMESTAMP(u.create_time))) ) + 1 AS rank_num FROM user u WHERE u.id != 1
AND u.name LIKE CONCAT('%', #{name}, '%')
) SELECT * FROM ranked_users ORDER BY rating DESC, create_time ASC LIMIT #{offset}, #{size}
